using Godot;
using System;
using System.Collections.Generic;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class ActorTimelineOperations
{
    private readonly ActorAudioOperations _audio=new();
    private static bool Overlaps(double start,double duration,double other,double length)=>start<other+length-.000001&&start+duration>other+.000001;
    public bool can_place(RefCounted owner,string id,double start,double duration,int layer)
    {
        int index=index_of(owner,id);var clips=Clips(owner);var actors=Actors(owner);double minimum=index>=0?minimum_duration(owner,clips[index].As<Resource>()):.1;if(layer<0||start<0||duration<minimum-.000001||!double.IsFinite(start)||!double.IsFinite(duration))return false;var actor=index>=0?actors[index].As<Resource>():null;string section=actor!=null?actor.Get("section_id").AsString():owner.Get("selected_section_id").AsString();for(int i=0;i<clips.Count;i++){var other=clips[i].As<Resource>();if(actors[i].As<Resource>().Get("section_id").AsString()!=section)continue;if(actor!=null&&!actors_obstruct(owner,actor,actor_for_id(owner,other.Get("actor_id").AsString())))continue;if(other.Get("id").AsString()!=id&&other.Get("layer").AsInt32()==layer&&Overlaps(start,duration,other.Get("start_time").AsDouble(),other.Get("duration").AsDouble()))return false;}return true;
    }
    public double nearest_free_start(RefCounted owner,string id,double desired,double duration,int layer)
    {
        desired=Math.Max(0,desired);if(can_place(owner,id,desired,duration,layer))return desired;var candidates=new List<double>{0};int index=index_of(owner,id);var clips=Clips(owner);var clip=clips.Count>0?clips[index>=0?index:clips.Count-1].As<Resource>():null;var actor=clip!=null?actor_for_id(owner,clip.Get("actor_id").AsString()):null;foreach(var item in section_clips(owner)){var other=item.As<Resource>();if(!actors_obstruct(owner,actor,actor_for_id(owner,other.Get("actor_id").AsString())))continue;if(other.Get("id").AsString()!=id&&other.Get("layer").AsInt32()==layer){candidates.Add(other.Get("start_time").AsDouble()-duration);candidates.Add(other.Get("start_time").AsDouble()+other.Get("duration").AsDouble());}}double best=double.PositiveInfinity,distance=double.PositiveInfinity;foreach(double candidate in candidates)if(can_place(owner,id,candidate,duration,layer)){double delta=Math.Abs(candidate-desired);if(delta<distance||Mathf.IsEqualApprox(delta,distance)&&candidate<best){best=candidate;distance=delta;}}return double.IsInfinity(best)?desired:best;
    }
    public bool can_place_group(RefCounted owner,Settings states)
    {
        var clips=Clips(owner);var actors=Actors(owner);for(int index=0;index<clips.Count;index++){var clip=clips[index].As<Resource>();var state=Get(states,clip.Get("id").AsString(),new Settings()).AsGodotDictionary();double start=Get(state,"start",clip.Get("start_time")).AsDouble(),duration=Get(state,"duration",clip.Get("duration")).AsDouble();int layer=Get(state,"layer",clip.Get("layer")).AsInt32();if(!_audio.valid(actors[index].As<Resource>(),clip,duration,Get(state,"offset",clip.Get("source_offset")).AsDouble()))return false;if(start<0||duration<minimum_duration(owner,clip)-.000001||layer<0)return false;for(int otherIndex=index+1;otherIndex<clips.Count;otherIndex++){var other=clips[otherIndex].As<Resource>();if(states.Count>0&&!states.ContainsKey(clip.Get("id"))&&!states.ContainsKey(other.Get("id")))continue;if(!actors_obstruct(owner,actors[index].As<Resource>(),actors[otherIndex].As<Resource>()))continue;var otherState=Get(states,other.Get("id").AsString(),new Settings()).AsGodotDictionary();double otherStart=Get(otherState,"start",other.Get("start_time")).AsDouble(),otherDuration=Get(otherState,"duration",other.Get("duration")).AsDouble();int otherLayer=Get(otherState,"layer",other.Get("layer")).AsInt32();if(layer==otherLayer&&Overlaps(start,duration,otherStart,otherDuration))return false;}}return true;
    }
    public double nearest_free_group_delta(RefCounted owner,GArray ids,double desired,int layerDelta)
    {
        var candidates=new List<double>{desired};double minimum=double.NegativeInfinity;foreach(var value in ids){int index=index_of(owner,value.AsString());if(index<0)continue;var clip=Clips(owner)[index].As<Resource>();double start=clip.Get("start_time").AsDouble();minimum=Math.Max(minimum,-start);foreach(var item in section_clips(owner)){var other=item.As<Resource>();if(!actors_obstruct(owner,actor_for_id(owner,clip.Get("actor_id").AsString()),actor_for_id(owner,other.Get("actor_id").AsString()))||ids.Contains(other.Get("id"))||other.Get("layer").AsInt32()!=clip.Get("layer").AsInt32()+layerDelta)continue;candidates.Add(other.Get("start_time").AsDouble()+other.Get("duration").AsDouble()-start);candidates.Add(other.Get("start_time").AsDouble()-clip.Get("duration").AsDouble()-start);}}desired=Math.Max(desired,minimum);candidates.Add(minimum);double best=desired,distance=double.PositiveInfinity;foreach(double entry in candidates){double candidate=Math.Max(entry,minimum);var states=new Settings();foreach(var value in ids){int index=index_of(owner,value.AsString());if(index<0)continue;var clip=Clips(owner)[index].As<Resource>();states[value]=new Settings{["start"]=clip.Get("start_time").AsDouble()+candidate,["duration"]=clip.Get("duration"),["layer"]=clip.Get("layer").AsInt32()+layerDelta,["offset"]=clip.Get("source_offset")};}if(can_place_group(owner,states)){double next=Math.Abs(candidate-desired);if(next<distance){best=candidate;distance=next;}}}return best;
    }
    private static Settings ClipState(Resource clip)=>new(){["start"]=clip.Get("start_time"),["duration"]=clip.Get("duration"),["layer"]=clip.Get("layer"),["offset"]=clip.Get("source_offset")};
    public void commit_clip_states(RefCounted owner,Settings states,string label,string primary)
    {
        if(states.Count==0||!can_place_group(owner,states))return;var committed=states.Duplicate(true);var original=new Settings();bool changed=false;foreach(var entry in committed){int index=index_of(owner,entry.Key.AsString());if(index<0)return;var clip=Clips(owner)[index].As<Resource>();original[entry.Key]=ClipState(clip);var state=entry.Value.AsGodotDictionary();changed|=!Mathf.IsEqualApprox(clip.Get("start_time").AsDouble(),state["start"].AsDouble())||!Mathf.IsEqualApprox(clip.Get("duration").AsDouble(),state["duration"].AsDouble())||clip.Get("layer").AsInt32()!=state["layer"].AsInt32()||!Mathf.IsEqualApprox(clip.Get("source_offset").AsDouble(),state["offset"].AsDouble());}if(!changed)return;History(owner,label,"_set_clip_states",new GArray{committed,primary},"_set_clip_states",new GArray{original,primary});Changed(owner);
    }
    public bool preview_clip_states(RefCounted owner,Settings states,string primary){if(states.Count==0||!can_place_group(owner,states))return false;set_clip_states(owner,states,primary);return true;}
    public void commit_clip_state_preview(RefCounted owner,Settings original,Settings final,string label,string primary){if(original.Count==0||final.Count==0||!can_place_group(owner,final))return;History(owner,label,"_set_clip_states",new GArray{final.Duplicate(true),primary},"_set_clip_states",new GArray{original.Duplicate(true),primary});Changed(owner);}
    public void set_clip_states(RefCounted owner,Settings states,string primary){foreach(var entry in states){int index=index_of(owner,entry.Key.AsString());if(index<0)continue;var clip=Clips(owner)[index].As<Resource>();var state=entry.Value.AsGodotDictionary();clip.Set("start_time",state["start"]);clip.Set("duration",state["duration"]);clip.Set("layer",state["layer"]);clip.Set("source_offset",state["offset"]);clip.EmitChanged();}make_primary(owner,primary);var selected=selected_clip(owner);if(selected!=null)owner.Set("selected_layer",selected.Get("layer"));Changed(owner);}
}
